const crypto = require('crypto');
function sign(body) {
  const secret = $env.LENDLOOP_CALLBACK_SECRET;
  if (!secret) throw new Error('LENDLOOP_CALLBACK_SECRET is not set');
  const t = Math.floor(Date.now() / 1000);
  const v1 = crypto.createHmac('sha256', secret).update(t + '.' + body).digest('hex');
  return 't=' + t + ',v1=' + v1;
}
const e = $input.first().json;
const workflow = (e.workflow && e.workflow.name) || 'unknown workflow';
const executionId = String((e.execution && e.execution.id) || ('trigger-' + Date.now()));
const error = (e.execution && e.execution.error) || (e.trigger && e.trigger.error) || {};
const node = e.execution && e.execution.lastNodeExecuted ? ' at "' + e.execution.lastNodeExecuted + '"' : '';
const message = ('Failed' + node + ': ' + (error.message || 'unknown error')).slice(0, 1900);
console.error('[LendLoop] ' + workflow + ' ' + executionId + ' ' + message);
const body = JSON.stringify({ workflow, executionId, message });
return [{ json: { body, signature: sign(body) } }];
